  const imported=highlightData(users),profile={handle,name:text(first('full_name')||rawName||handle,200),bio:biography,avatar,followers:countFrom(users.flatMap(u=>[u.followers_count,u.follower_count,u.edge_followed_by?.count]),capture('Followers|seguidores')),following:countFrom(users.flatMap(u=>[u.following_count,u.follows_count,u.edge_follow?.count]),capture('Following|seguidos|siguiendo')),posts:countFrom(users.flatMap(u=>[u.posts_count,u.media_count,u.edge_owner_to_timeline_media?.count]),capture('Posts|publicaciones|publicaç[õo]es')),verified:!!(first('is_verified')??first('verified')),private:!!first('is_private'),link:text(first('external_url'),2000),highlights:imported.highlights,category:text(first('category_name'),200),pronouns:Array.isArray(first('pronouns'))?first('pronouns').filter(v=>typeof v==='string').join(' / '):text(first('pronouns'),200)};
